<script setup>
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import api from '../api'
const sidebarOpen=ref(false), searchQuery=ref(''), items=ref([]), showReportModal=ref(false), showReportSuccess=ref(false), reportReason=ref(''), reportDetails=ref('')
const filteredItems=computed(()=>items.value.filter(item=>!searchQuery.value||item.title?.toLowerCase().includes(searchQuery.value.toLowerCase())))
onMounted(async()=>{try{items.value=(await api.get('/items?status=claimed')).data}catch{items.value=[]}})
const openReport=()=>{reportReason.value='';reportDetails.value='';showReportModal.value=true}; const closeReport=()=>showReportModal.value=false; const submitReport=()=>{showReportModal.value=false;showReportSuccess.value=true}
</script>
<template><div class="ch-wrapper"><div v-if="sidebarOpen" class="overlay" @click="sidebarOpen=false"></div><div class="sidebar" :class="{open:sidebarOpen}"><div class="sidebar-top"><div class="sidebar-brand"><div class="sidebar-logo">⌂</div><div><p class="sidebar-title">LDCU iFound</p><p class="sidebar-sub">Lost &amp; Found System</p></div></div><button class="close-btn" @click="sidebarOpen=false">✕</button></div><nav class="sidebar-nav"><RouterLink to="/dashboard" class="nav-item">Dashboard</RouterLink><RouterLink to="/lost-and-found" class="nav-item">Lost &amp; Found</RouterLink><RouterLink to="/claims" class="nav-item">Claims Management</RouterLink><RouterLink to="/history" class="nav-item active">Claimed History</RouterLink><RouterLink to="/messages" class="nav-item">Messages</RouterLink><RouterLink to="/post-item" class="nav-item">Post Item</RouterLink><RouterLink to="/profile" class="nav-item">My Profile</RouterLink></nav><div class="sidebar-footer">© 2025 LDCU iFound System</div></div><div class="main"><div class="topbar"><button class="menu-btn" @click="sidebarOpen=!sidebarOpen">☰</button><div class="topbar-brand"><div class="topbar-logo">⌂</div><div><p class="topbar-name">LDCU iFound</p><p class="topbar-sub">Lost &amp; Found System</p></div></div></div><div class="content"><div class="page-header"><h2>Claimed Items History</h2><p>Successful returns and claimed items</p></div><div class="search-bar">⌕<input v-model="searchQuery" placeholder="Search claimed items..." /></div><div class="items-grid"><div v-for="item in filteredItems" :key="item.id" class="item-card"><div class="item-img-wrapper"><img :src="item.image_url||item.image||'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?w=400&q=80'" :alt="item.title||item.name" /><div class="flag-btn" @click="openReport">⚑</div><div class="returned-badge">✓ RETURNED</div></div><div class="item-info"><h4>{{item.title||item.name}}</h4><p class="item-meta">⌖ {{item.location}}</p><p class="item-meta">▣ Found: {{item.foundDate||item.date_found}}</p><p class="item-meta">♙ Posted by: <strong>{{item.postedBy||item.posted_by_name}}</strong></p><p class="item-meta returned-date">▣ Returned: <strong>{{item.returnedDate}}</strong></p></div></div></div></div></div><div v-if="showReportModal" class="modal-overlay" @click="closeReport"></div><div v-if="showReportModal" class="modal"><h3>Report a Problem <button class="modal-close" @click="closeReport">✕</button></h3><div class="modal-form"><input v-model="reportReason" placeholder="Reason for Report"/><textarea v-model="reportDetails" rows="5" placeholder="Please provide details"></textarea></div><div class="modal-footer"><button class="btn-cancel" @click="closeReport">Cancel</button><button class="btn-report" @click="submitReport">Submit Report</button></div></div><div v-if="showReportSuccess" class="modal success-modal"><h3>Report Submitted!</h3><p>Staff will review this dispute shortly.</p></div></div></template>
<style scoped>
