tive;height:200px}.item-img-wrapper img{width:100%;height:100%;object-fit:cover}.flag-btn{position:absolute;top:10px;left:10px;background:#fff;padding:7px;border-radius:6px;cursor:pointer}.returned-badge{position:absolute;top:10px;right:10px;background:#22c55e;color:#fff;padding:4px 10px;border-radius:6px;font-size:.75rem}.item-info{padding:16px}.item-info h4{margin-bottom:10px}.item-meta{font-size:.82rem;color:#666;margin-bottom:6px}.returned-date{color:#16a34a}.modal{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#fff;padding:28px;border-radius:16px;width:90%;max-width:560px;z-index:201}.modal-header,.modal-footer{display:flex;justify-content:space-between;gap:12px}.modal-form{display:flex;flex-direction:column;gap:12px;margin-top:20px}.modal-form input,.modal-form textarea{padding:11px;border:1px solid #dde1e9;border-radius:10px}.btn-cancel,.btn-report{flex:1;padding:13px;border:0;border-radius:10px}.btn-report{background:#ef4444;color:#fff}.modal-footer{margin-top:20px}.success-modal{text-align:center}@media(max-width:900px){.items-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.items-grid{grid-template-columns:1fr}.content{padding:16px}}
